-- Hotel MVP Phase 0/1: tenant/property isolation and append-only financial evidence.
CREATE TABLE "hotel_rate_plans" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"roomTypeId" text NOT NULL,"nightlyRateMinor" integer NOT NULL CHECK ("nightlyRateMinor">=0),"taxConfig" jsonb NOT NULL,"currency" text NOT NULL,"active" boolean NOT NULL DEFAULT true,"validFrom" date NOT NULL,"validTo" date,UNIQUE("organizationId","branchId","id"));
CREATE TABLE "hotel_reservations" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"confirmationNumber" text NOT NULL,"status" text NOT NULL,"arrivalDate" date NOT NULL,"departureDate" date NOT NULL,"currency" text NOT NULL,"version" integer NOT NULL DEFAULT 1,UNIQUE("organizationId","branchId","id"));
CREATE TABLE "hotel_reservation_stay_units" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"reservationId" text NOT NULL,"roomTypeId" text NOT NULL,"ratePlanId" text NOT NULL,"nightlyRateMinor" integer NOT NULL,"netMinorPerNight" integer NOT NULL,"taxMinorPerNight" integer NOT NULL,"totalMinorPerNight" integer NOT NULL,"taxSnapshot" jsonb NOT NULL,"currency" text NOT NULL,UNIQUE("organizationId","branchId","id"));
CREATE TABLE "hotel_folios" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"reservationId" text NOT NULL,"folioNumber" text NOT NULL,"status" text NOT NULL,"currency" text NOT NULL,"version" integer NOT NULL DEFAULT 1,UNIQUE("organizationId","branchId","id"));
CREATE TABLE "hotel_folio_postings" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"folioId" text NOT NULL,"kind" text NOT NULL,"reversesPostingId" text,"unitAmountMinor" integer NOT NULL,"netMinor" integer NOT NULL,"taxMinor" integer NOT NULL,"totalMinor" integer NOT NULL,"currency" text NOT NULL,"reason" text,UNIQUE("organizationId","branchId","id"),FOREIGN KEY("organizationId","branchId","reversesPostingId") REFERENCES "hotel_folio_postings"("organizationId","branchId","id"));
CREATE TABLE "hotel_folio_payments" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"folioId" text NOT NULL,"amountMinor" integer NOT NULL,"currency" text NOT NULL,"refundsPaymentId" text,UNIQUE("organizationId","branchId","id"),FOREIGN KEY("organizationId","branchId","refundsPaymentId") REFERENCES "hotel_folio_payments"("organizationId","branchId","id"));
CREATE TABLE "hotel_room_assignments" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"stayUnitId" text NOT NULL,"roomId" text NOT NULL,"version" integer NOT NULL DEFAULT 1,UNIQUE("organizationId","branchId","id"));
CREATE TABLE "hotel_reservation_events" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"reservationId" text NOT NULL,"kind" text NOT NULL);
CREATE TABLE "hotel_operation_idempotency_keys" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"scope" text NOT NULL,"key" text NOT NULL,UNIQUE("organizationId","branchId","scope","key"));
CREATE TABLE "hotel_night_audit_runs" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"businessDate" date NOT NULL,UNIQUE("organizationId","branchId","id"));
CREATE TABLE "hotel_daily_snapshots" ("id" text PRIMARY KEY,"organizationId" text NOT NULL,"branchId" text NOT NULL,"auditRunId" text NOT NULL,"roomRevenueMinor" integer NOT NULL,"taxMinor" integer NOT NULL,"currency" text NOT NULL,UNIQUE("organizationId","branchId","id"));

CREATE FUNCTION hotel_reject_immutable_money() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'hotel financial evidence is append-only' USING ERRCODE='55000'; END $$;
CREATE TRIGGER hotel_rate_snapshot_immutable BEFORE UPDATE OR DELETE ON "hotel_reservation_stay_units" FOR EACH ROW EXECUTE FUNCTION hotel_reject_immutable_money();
CREATE TRIGGER hotel_posting_immutable BEFORE UPDATE OR DELETE ON "hotel_folio_postings" FOR EACH ROW EXECUTE FUNCTION hotel_reject_immutable_money();
CREATE TRIGGER hotel_payment_immutable BEFORE UPDATE OR DELETE ON "hotel_folio_payments" FOR EACH ROW EXECUTE FUNCTION hotel_reject_immutable_money();
CREATE TRIGGER hotel_snapshot_immutable BEFORE UPDATE OR DELETE ON "hotel_daily_snapshots" FOR EACH ROW EXECUTE FUNCTION hotel_reject_immutable_money();
CREATE FUNCTION hotel_validate_reversal() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE original record; BEGIN IF NEW."reversesPostingId" IS NULL OR coalesce(btrim(NEW.reason),'')='' THEN RAISE EXCEPTION 'correction requires linked reversal and reason'; END IF; SELECT * INTO original FROM hotel_folio_postings WHERE "organizationId"=NEW."organizationId" AND "branchId"=NEW."branchId" AND id=NEW."reversesPostingId" FOR SHARE; IF NOT FOUND OR NEW.currency<>original.currency OR NEW."totalMinor"<>-original."totalMinor" THEN RAISE EXCEPTION 'reversal must match original scope, currency, and amount'; END IF; RETURN NEW; END $$;
CREATE TRIGGER hotel_reversal_valid BEFORE INSERT ON "hotel_folio_postings" FOR EACH ROW WHEN (NEW.kind='REVERSAL') EXECUTE FUNCTION hotel_validate_reversal();

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['hotel_rate_plans','hotel_reservations','hotel_reservation_stay_units','hotel_folios','hotel_folio_postings','hotel_folio_payments','hotel_room_assignments','hotel_reservation_events','hotel_operation_idempotency_keys','hotel_night_audit_runs','hotel_daily_snapshots'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY hotel_scope ON %I USING ("organizationId"=current_setting(''app.current_organization_id'',true) AND "branchId"=current_setting(''app.current_hotel_property_id'',true)) WITH CHECK ("organizationId"=current_setting(''app.current_organization_id'',true) AND "branchId"=current_setting(''app.current_hotel_property_id'',true))',t); END LOOP; END $$;
